<script setup>
import {ref} from 'vue';import {Head,useForm,usePage,router,Link} from '@inertiajs/vue3';import Settings from '../Components/Settings.vue';import Errors from '../Components/Errors.vue';import {art} from '../art';
const props=defineProps({catalog:Object,exams:Object,students:Array}),page=usePage();
const form=useForm({title:'SUSHI Comprehensive Exam',mode:'tutor',count:25,subjects:[...props.catalog.subjects],topics:[],difficulty:'All',pool:'all',seed:Math.floor(Math.random()*4294967296),balance:true,minutes:30});
const assigning=ref(null),assignment=useForm({students:[],opens_at:'',closes_at:'',minutes:60,max_attempts:1,release_answers:false});
function assign(){assignment.transform(d=>({...d,opens_at:new Date(d.opens_at).toISOString(),closes_at:new Date(d.closes_at).toISOString()})).post('/admin/exams/'+assigning.value+'/assign',{preserveScroll:true,onSuccess:()=>assigning.value=null})}
function build(){form.topics=form.topics.filter(t=>form.subjects.includes(t.split('\u001f')[0]));form.post('/exams',{preserveScroll:true})}
</script><template><Head title="Bento Builder"/><div class="page-title"><div><p class="eyebrow">Make a custom exam</p><h1>Bento Builder</h1><p>Save a reproducible exam, then download its paper, answer sheet, and key.</p></div><img class="portrait" :src="art.chef" alt="Sushi chef"></div>
<form class="panel" @submit.prevent="build"><label>Exam title<input v-model="form.title" required maxlength="150"></label><Settings :form="form" :catalog="catalog" exam/><Errors :errors="form.errors"/><button class="primary" :disabled="form.processing">Save exam</button></form>
<div class="row"><h2>Saved exam bentos</h2><button @click="router.reload({only:['exams']})">Refresh export status</button></div>
<article v-for="exam in exams.data" :key="exam.id" class="panel"><h2>{{exam.title}}</h2><p>{{exam.code}} · {{exam.items_count}} questions · Seed {{exam.settings.seed}}</p><div class="row spaced"><button @click="router.post('/exams/'+exam.id+'/export',{explanations:true},{preserveScroll:true})">Generate PDFs with explanations</button><button @click="router.post('/exams/'+exam.id+'/export',{explanations:false},{preserveScroll:true})">Generate compact key</button><button v-if="page.props.user.role==='admin'" @click="assigning=exam.id">Assign to learners</button></div><div v-for="ex in exam.exports" :key="ex.id" class="export-row"><span>Export {{ex.id}} · {{ex.status}}</span><template v-if="ex.status==='ready'"><a :href="'/exports/'+ex.id+'/paper'">Exam PDF</a><a :href="'/exports/'+ex.id+'/sheet'">Answer sheet PDF</a><a :href="'/exports/'+ex.id+'/key'">Answer key PDF</a></template><span v-if="ex.error" class="error">{{ex.error}}</span></div>
<form v-if="assigning===exam.id" class="inset" @submit.prevent="assign"><h3>Assign this exam</h3><div class="form-grid"><label v-for="student in students" class="check"><input type="checkbox" v-model="assignment.students" :value="student.id">{{student.username}}</label><label>Opens (your local time)<input v-model="assignment.opens_at" type="datetime-local" required></label><label>Closes (your local time)<input v-model="assignment.closes_at" type="datetime-local" required></label><label>Minutes per attempt<input v-model.number="assignment.minutes" type="number" min="1" max="360"></label><label>Attempt limit<input v-model.number="assignment.max_attempts" type="number" min="1" max="20"></label><label class="check"><input v-model="assignment.release_answers" type="checkbox">Release explanations after submission</label></div><Errors :errors="assignment.errors"/><button class="primary" :disabled="assignment.processing">Save assignment</button></form></article>
<p v-if="!exams.data.length">Your saved exams will appear here.</p><div class="row"><Link v-if="exams.prev_page_url" :href="exams.prev_page_url">Previous</Link><Link v-if="exams.next_page_url" :href="exams.next_page_url">Next</Link></div>
</template>
